    /// Verify and install into `store`. Idempotent: an installed pack's blobs are skipped by the
    /// store and its manifest is rewritten with the same bytes.
    @discardableResult
    static func install(into store: StickerPackStore = .default()) throws -> StickerPack {
        let manifest = manifestBytes
        let pack = try StickerPack.verify(manifestBytes: manifest, allowUnsigned: true)
        try store.install(pack, manifestBytes: manifest) { entry in
            blobsHex[entry.sha256.map { String(format: "%02x", $0) }.joined()].map { Data(hex: $0) }
        }
        try store.setInstalled(pack.id, true)
        return pack
